"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[8685],{8685:function(e,a,o){o.d(a,{dZ:function(){return c},f3:function(){return r},jP:function(){return n},l4:function(){return t},r1:function(){return d}});var s=o(8530);let i=s.be,n=[{slug:"privacidade",title:"Pol\xedtica de Privacidade",emoji:"\uD83D\uDD12",summary:"Como o ".concat(s.iC," recolhe, usa, partilha e protege os teus dados pessoais."),sections:[{h:"1. Quem somos",p:["O ".concat(s.iC," \xe9 uma plataforma mo\xe7ambicana de gaming (clipes, lives, torneios, loja e eventos) operada por ").concat(s.j1,". Respons\xe1vel pelo tratamento de dados: ").concat(s.j1,". Contacto: ").concat(i,".")]},{h:"2. Dados que recolhemos",p:["Conta: nome, nome de utilizador, email e/ou n\xfamero de telem\xf3vel, data de nascimento (para verificar a idade m\xednima), prov\xedncia, fotografia/avatar e palavra-passe (guardada cifrada pelo fornecedor de autentica\xe7\xe3o).","Conte\xfado que publicas: clipes, publica\xe7\xf5es, coment\xe1rios, mensagens em canais e chats de lives, den\xfancias.","Atividade: gostos, seguidores, visualiza\xe7\xf5es, inscri\xe7\xf5es em torneios, compras, miss\xf5es, tempo de ecr\xe3 (funcionalidade de bem-estar).","Pagamentos: valor, m\xe9todo (M-Pesa, e-Mola, cart\xe3o) e estado. N\xe3o guardamos o PIN nem os dados completos do cart\xe3o — s\xe3o tratados pelo agregador de pagamentos.","Dispositivo e t\xe9cnicos: tipo de dispositivo, sistema, idioma, identificadores de notifica\xe7\xf5es push, registos de erros e endere\xe7o IP (seguran\xe7a e preven\xe7\xe3o de fraude).","An\xfancios: impress\xf5es e cliques em an\xfancios patrocinados, para medir resultados e cobrar anunciantes.","Mensagens diretas: conte\xfado das conversas 1:1 (texto e imagens), vis\xedvel apenas aos participantes; a modera\xe7\xe3o s\xf3 acede a mensagens denunciadas.","Seguran\xe7a e carteira: dispositivos, IP e hist\xf3rico de in\xedcios de sess\xe3o, PIN de transa\xe7\xe3o (guardado apenas como hash), n\xfameros M-Pesa/e-Mola da lista branca e, se pedires um n\xedvel de verifica\xe7\xe3o mais alto, fotografia do documento e selfie (armazenamento privado, apagados 30 dias ap\xf3s a decis\xe3o salvo obriga\xe7\xe3o legal).","Criadores: ganhos, presentes recebidos, membros e levantamentos."]},{h:"3. Para que usamos",p:["Prestar o servi\xe7o (conta, feed, lives, torneios, loja, bilhetes); processar pagamentos; seguran\xe7a, modera\xe7\xe3o e preven\xe7\xe3o de fraude e abuso; cumprir obriga\xe7\xf5es legais; enviar notifica\xe7\xf5es que ativaste; mostrar an\xfancios (personalizados apenas se consentires; caso contr\xe1rio, an\xfancios contextuais); estat\xedsticas agregadas para melhorar a app.","Base legal: execu\xe7\xe3o do contrato (Termos de Uso), consentimento (an\xfancios personalizados, notifica\xe7\xf5es push, an\xe1lises opcionais), interesse leg\xedtimo (seguran\xe7a e modera\xe7\xe3o) e obriga\xe7\xe3o legal."]},{h:"4. Com quem partilhamos",p:["Fornecedores que tratam dados por nossa conta: alojamento e base de dados (Supabase), envio de email e SMS, agregador de pagamentos M-Pesa/e-Mola, notifica\xe7\xf5es push (Google Firebase Cloud Messaging / Web Push).","Anunciantes recebem apenas relat\xf3rios agregados (impress\xf5es, cliques, alcance por prov\xedncia/idade), nunca a tua identidade.","Autoridades, quando a lei o exigir, incluindo den\xfancias obrigat\xf3rias de explora\xe7\xe3o sexual de menores.","N\xe3o vendemos os teus dados pessoais."]},{h:"5. Conte\xfado p\xfablico",p:["O teu perfil, clipes, publica\xe7\xf5es e coment\xe1rios s\xe3o vis\xedveis para outros utilizadores. Podes bloquear utilizadores e apagar o teu conte\xfado a qualquer momento."]},{h:"6. Menores",p:["A idade m\xednima \xe9 ".concat(s.G3," anos. Contas de menores de 18 anos t\xeam mensagens diretas limitadas a quem seguem, an\xfancios n\xe3o personalizados e compras sujeitas a autoriza\xe7\xe3o do encarregado de educa\xe7\xe3o. Ver Normas de Seguran\xe7a Infantil.")]},{h:"7. Conserva\xe7\xe3o",p:["Mantemos os dados enquanto a conta existir. Ap\xf3s pedido de elimina\xe7\xe3o, a conta \xe9 desativada de imediato e os dados s\xe3o apagados em at\xe9 30 dias, exceto registos de pagamentos (guardados at\xe9 10 anos por obriga\xe7\xe3o fiscal) e dados necess\xe1rios para investigar abuso ou cumprir ordens legais."]},{h:"8. Seguran\xe7a",p:["Liga\xe7\xf5es cifradas (HTTPS/TLS), dados cifrados em repouso no fornecedor, controlo de acesso por regras de seguran\xe7a ao n\xedvel das linhas (RLS), palavras-passe com hash e acesso administrativo registado num log de auditoria."]},{h:"9. Os teus direitos",p:["Aceder, corrigir, exportar e apagar os teus dados; retirar consentimentos; opor-te a an\xfancios personalizados. Em Defini\xe7\xf5es ou por email para ".concat(i,". Respondemos em at\xe9 30 dias. Elimina\xe7\xe3o: ").concat(s._O,"/eliminar-conta/")]},{h:"10. Transfer\xeancias internacionais",p:["Os nossos fornecedores podem alojar dados fora de Mo\xe7ambique (ex.: UE/EUA), com garantias contratuais adequadas."]},{h:"11. Altera\xe7\xf5es",p:["Avisamos na app antes de altera\xe7\xf5es importantes. \xdaltima atualiza\xe7\xe3o: ".concat(s.MV,".")]}]},{slug:"termos",title:"Termos de Uso",emoji:"\uD83D\uDCDC",summary:"Regras de utiliza\xe7\xe3o do ".concat(s.iC,". Ao criar conta aceitas estes termos."),sections:[{h:"1. Aceita\xe7\xe3o",p:["Ao usar o ".concat(s.iC," aceitas estes Termos, a Pol\xedtica de Privacidade e as Diretrizes da Comunidade. Tens de ter pelo menos ").concat(s.G3," anos. Menores de 18 precisam de autoriza\xe7\xe3o do encarregado de educa\xe7\xe3o para compras.")]},{h:"2. A tua conta",p:["\xc9s respons\xe1vel pela seguran\xe7a da conta e pela informa\xe7\xe3o verdadeira. Uma pessoa, uma conta pessoal. N\xe3o partilhes c\xf3digos de verifica\xe7\xe3o."]},{h:"3. O teu conte\xfado",p:["Mant\xe9ns os direitos sobre o que publicas. D\xe1s-nos uma licen\xe7a n\xe3o exclusiva, gratuita e mundial para alojar, mostrar e distribuir esse conte\xfado dentro do servi\xe7o e na sua promo\xe7\xe3o. S\xf3 publicas conte\xfado que tens direito a partilhar."]},{h:"4. Condutas proibidas",p:["Violar as Diretrizes da Comunidade; burlas (ex.: “diamantes gr\xe1tis”), venda de contas roubadas, batota/hacks, ass\xe9dio, discurso de \xf3dio, conte\xfado sexual, explora\xe7\xe3o de menores, viol\xeancia, spam, viola\xe7\xe3o de direitos de autor e tentativa de aceder a dados de terceiros."]},{h:"5. Modera\xe7\xe3o",p:["Podemos remover conte\xfado, limitar, suspender ou banir contas que violem as regras. Podes contestar por email. Den\xfancias s\xe3o revistas normalmente em 24 h."]},{h:"6. Compras, moedas e torneios",p:["Pre\xe7os em Meticais (MZN) com IVA inclu\xeddo, sempre mostrados antes de pagar. Moedas e presentes s\xe3o bens digitais sem valor fora da app e n\xe3o s\xe3o convert\xedveis em dinheiro, exceto levantamentos de criadores eleg\xedveis. Torneios com inscri\xe7\xe3o paga s\xe3o competi\xe7\xf5es de habilidade; regras e distribui\xe7\xe3o de pr\xe9mios aparecem em cada torneio. Ver Pol\xedtica de Reembolsos."]},{h:"7. Assinaturas",p:["Planos mensais renovam automaticamente at\xe9 cancelares. Podes cancelar a qualquer momento no Perfil; o acesso mant\xe9m-se at\xe9 ao fim do per\xedodo pago."]},{h:"8. An\xfancios",p:["Anunciantes s\xe3o respons\xe1veis pelos seus an\xfancios, que passam por revis\xe3o. N\xe3o s\xe3o permitidos an\xfancios enganosos, de jogos de azar, \xe1lcool/tabaco para menores, ou conte\xfado para adultos."]},{h:"9. Limita\xe7\xe3o de responsabilidade",p:["O servi\xe7o \xe9 fornecido “tal como est\xe1”. N\xe3o somos respons\xe1veis por perdas indiretas nem por conte\xfado de terceiros, na medida permitida pela lei mo\xe7ambicana."]},{h:"10. Lei aplic\xe1vel",p:["Lei da Rep\xfablica de Mo\xe7ambique. Contacto: ".concat(i,". \xdaltima atualiza\xe7\xe3o: ").concat(s.MV,".")]}]},{slug:"diretrizes",title:"Diretrizes da Comunidade",emoji:"\uD83E\uDD1D",summary:"O que \xe9 e n\xe3o \xe9 permitido no GAME HUB. Respeito acima de tudo.",sections:[{h:"Respeito",p:["Sem ass\xe9dio, bullying, amea\xe7as, discurso de \xf3dio (ra\xe7a, etnia, religi\xe3o, g\xe9nero, orienta\xe7\xe3o sexual, defici\xeancia, origem) nem doxxing (publicar dados pessoais de outros)."]},{h:"Seguran\xe7a de menores",p:["Toler\xe2ncia zero para qualquer conte\xfado que sexualize menores, aliciamento (grooming) ou pedidos de imagens. Estas contas s\xe3o banidas e denunciadas \xe0s autoridades."]},{h:"Conte\xfado sexual e violento",p:["Proibida nudez e conte\xfado sexual. Viol\xeancia real gr\xe1fica, automutila\xe7\xe3o e incentivo a suic\xeddio s\xe3o proibidos. Viol\xeancia de videojogos \xe9 permitida."]},{h:"Jogo limpo",p:["Sem hacks, batota, emuladores onde proibido, venda/compra de contas roubadas, burlas de diamantes ou recargas falsas."]},{h:"Spam e enganos",p:["Sem spam, links maliciosos, sorteios falsos, esquemas de pir\xe2mide ou apostas."]},{h:"Propriedade intelectual",p:["Publica apenas conte\xfado teu ou que tens autoriza\xe7\xe3o para usar."]},{h:"Como denunciar",p:["Toca em ⋯ em qualquer clipe, publica\xe7\xe3o, coment\xe1rio, live ou perfil → Denunciar. Podes tamb\xe9m Bloquear o utilizador. Revemos em at\xe9 24 h."]},{h:"Consequ\xeancias",p:["Aviso, remo\xe7\xe3o de conte\xfado, restri\xe7\xe3o de funcionalidades, suspens\xe3o tempor\xe1ria ou banimento permanente, conforme a gravidade."]}]},{slug:"seguranca-infantil",title:"Normas de Seguran\xe7a Infantil (CSAE)",emoji:"\uD83D\uDEE1️",summary:"Normas publicadas contra o abuso e a explora\xe7\xe3o sexual de crian\xe7as (CSAE), exigidas pela Google Play.",sections:[{h:"Compromisso",p:["O ".concat(s.iC," pro\xedbe de forma absoluta qualquer forma de abuso e explora\xe7\xe3o sexual de crian\xe7as (CSAE) e material de abuso sexual infantil (CSAM), incluindo aliciamento (grooming), sextors\xe3o, tr\xe1fico e sexualiza\xe7\xe3o de menores.")]},{h:"Idade m\xednima e prote\xe7\xf5es",p:["Idade m\xednima de ".concat(s.G3," anos com verifica\xe7\xe3o da data de nascimento no registo. Para menores de 18: mensagens diretas apenas de quem seguem, perfil com menos exposi\xe7\xe3o, sem an\xfancios personalizados, compras com autoriza\xe7\xe3o do encarregado, sil\xeancio noturno ativo por defeito.")]},{h:"Dete\xe7\xe3o e modera\xe7\xe3o",p:["Den\xfancia dispon\xedvel em todo o conte\xfado e perfis, com categoria “Seguran\xe7a de menores” tratada com prioridade m\xe1xima. Modera\xe7\xe3o humana, filtros de palavras e revis\xe3o de an\xfancios. Contas infratoras s\xe3o banidas de imediato e o conte\xfado preservado para as autoridades."]},{h:"Den\xfancia \xe0s autoridades",p:["Reportamos casos confirmados de CSAM \xe0s autoridades competentes em Mo\xe7ambique (PRM — Pol\xedcia da Rep\xfablica de Mo\xe7ambique, Gabinete de Atendimento \xe0 Fam\xedlia e Menores V\xedtimas de Viol\xeancia) e ao NCMEC / organismos internacionais aplic\xe1veis, conforme a lei."]},{h:"Contacto para seguran\xe7a infantil",p:["Ponto de contacto designado: ".concat(i," (assunto: “Seguran\xe7a Infantil”). Respondemos com prioridade. Em perigo imediato, contacta a pol\xedcia (119) ou a Linha Fala Crian\xe7a (116).")]},{h:"Conformidade",p:["Cumprimos as leis aplic\xe1veis de prote\xe7\xe3o de menores e as pol\xedticas da Google Play sobre normas de seguran\xe7a infantil. \xdaltima atualiza\xe7\xe3o: ".concat(s.MV,".")]}]},{slug:"seguranca-dados",title:"Seguran\xe7a dos Dados (resumo)",emoji:"\uD83D\uDCCA",summary:"Resumo para a sec\xe7\xe3o “Seguran\xe7a dos dados” da Google Play: o que \xe9 recolhido, partilhado e porqu\xea.",sections:[{h:"Dados recolhidos",p:["Informa\xe7\xf5es pessoais: nome, email, telem\xf3vel, ID de utilizador, data de nascimento — funcionalidade da app, gest\xe3o de conta, seguran\xe7a. Obrigat\xf3rio.","Informa\xe7\xf5es financeiras: hist\xf3rico de compras — funcionalidade, preven\xe7\xe3o de fraude. (Dados de cart\xe3o/PIN tratados pelo agregador, n\xe3o por n\xf3s.)","Fotos e v\xeddeos / conte\xfado gerado pelo utilizador: clipes, publica\xe7\xf5es, coment\xe1rios — funcionalidade. Opcional.","Mensagens na app: chats de lives e canais — funcionalidade, modera\xe7\xe3o.","Atividade na app: intera\xe7\xf5es, pesquisas, conte\xfado visto — funcionalidade, an\xe1lises, an\xfancios.","Localiza\xe7\xe3o aproximada: prov\xedncia (indicada por ti) — segmenta\xe7\xe3o de an\xfancios e torneios. N\xe3o recolhemos GPS.","Identificadores do dispositivo: token de notifica\xe7\xf5es push — notifica\xe7\xf5es.","Registos de falhas e diagn\xf3stico — an\xe1lises, seguran\xe7a."]},{h:"Partilha",p:["N\xe3o vendemos dados. Partilhamos com fornecedores de servi\xe7o (alojamento, pagamentos, email/SMS, push) que atuam por nossa conta. Anunciantes recebem apenas dados agregados."]},{h:"Pr\xe1ticas de seguran\xe7a",p:["Dados cifrados em tr\xe2nsito (HTTPS). Podes pedir a elimina\xe7\xe3o dos dados na app (Defini\xe7\xf5es › Eliminar conta) ou na web: "+s._O+"/eliminar-conta/"]}]},{slug:"cookies",title:"Cookies, Armazenamento e An\xfancios",emoji:"\uD83C\uDF6A",summary:"Como usamos armazenamento local e como funcionam os an\xfancios patrocinados.",sections:[{h:"Armazenamento local",p:["Usamos armazenamento local do navegador/dispositivo (localStorage, cache do service worker) para manter a sess\xe3o, prefer\xeancias, funcionamento offline e a vers\xe3o de demonstra\xe7\xe3o. N\xe3o usamos cookies de terceiros para rastreio entre sites."]},{h:"An\xfancios patrocinados",p:["Alguns itens no feed e nos clipes s\xe3o an\xfancios, marcados claramente como “Patrocinado”. S\xe3o vendidos pelo pr\xf3prio GAME HUB a anunciantes atrav\xe9s do Gestor de An\xfancios. N\xe3o usamos redes de an\xfancios de terceiros."]},{h:"Personaliza\xe7\xe3o",p:["Com o teu consentimento, usamos idade, prov\xedncia, jogos que segues e interesses para escolher an\xfancios. Sem consentimento (e sempre para menores de 18), mostramos apenas an\xfancios contextuais. Podes mudar em Defini\xe7\xf5es › Privacidade."]},{h:"Premium",p:["Assinantes Premium n\xe3o veem an\xfancios."]}]},{slug:"reembolsos",title:"Pol\xedtica de Reembolsos (bens digitais)",emoji:"\uD83D\uDCB8",summary:"Quando e como podes pedir reembolso de moedas, planos, inscri\xe7\xf5es e bilhetes.",sections:[{h:"Princ\xedpio",p:["Pre\xe7o final sempre vis\xedvel antes de pagar, sem custos escondidos. Cancelar uma assinatura \xe9 um toque."]},{h:"Moedas e presentes",p:["Moedas n\xe3o usadas: reembolso total at\xe9 14 dias ap\xf3s a compra. Moedas j\xe1 gastas em presentes n\xe3o s\xe3o reembols\xe1veis, exceto erro t\xe9cnico ou cobran\xe7a indevida."]},{h:"Assinaturas",p:["Podes cancelar a qualquer momento; n\xe3o h\xe1 renova\xe7\xe3o seguinte. Reembolso proporcional se pedires nos primeiros 7 dias da primeira subscri\xe7\xe3o ou em caso de falha do servi\xe7o."]},{h:"Inscri\xe7\xf5es em torneios",p:["Reembolso total se cancelares at\xe9 24 h antes do in\xedcio ou se o torneio for cancelado/adiado pelo organizador. Sem reembolso ap\xf3s o check-in ou em caso de desqualifica\xe7\xe3o por batota."]},{h:"Bilhetes de eventos",p:["Reembolso total se o evento for cancelado. Troca de titular gratuita at\xe9 48 h antes."]},{h:"Loja / marketplace",p:["Bens f\xedsicos: devolu\xe7\xe3o em 7 dias se o produto chegar danificado ou diferente do anunciado. Diamantes/recargas: reembolso se n\xe3o forem entregues em 24 h."]},{h:"Como pedir",p:["Perfil › Compras › Pedir reembolso, ou email para ".concat(i," com o ID do recibo. Reembolsos s\xe3o devolvidos ao mesmo m\xe9todo (M-Pesa/e-Mola/cart\xe3o) em at\xe9 10 dias \xfateis. Compras feitas pela Google Play seguem tamb\xe9m a pol\xedtica de reembolsos da Google Play.")]}]},{slug:"eliminar-conta",title:"Elimina\xe7\xe3o de Conta e Dados",emoji:"\uD83D\uDDD1️",summary:"Como eliminar a tua conta do GAME HUB e os dados associados, na app ou nesta p\xe1gina.",sections:[{h:"Na app",p:["Defini\xe7\xf5es › Conta › Eliminar conta. Confirmas com um c\xf3digo enviado para o teu email ou telem\xf3vel. A conta \xe9 desativada imediatamente."]},{h:"Sem acesso \xe0 app",p:["Preenche o formul\xe1rio abaixo ou envia email para ".concat(i," com o assunto “Eliminar conta” e o teu nome de utilizador, email ou telem\xf3vel associado. Podemos pedir confirma\xe7\xe3o para proteger a tua conta.")]},{h:"O que \xe9 apagado",p:["Perfil, email, telem\xf3vel, data de nascimento, clipes, publica\xe7\xf5es, coment\xe1rios, mensagens, seguidores, gostos, guardados, progresso (XP, miss\xf5es, conquistas), prefer\xeancias e tokens de notifica\xe7\xf5es."]},{h:"O que \xe9 mantido e por quanto tempo",p:["Registos de pagamentos e faturas: at\xe9 10 anos (obriga\xe7\xe3o fiscal). Registos de modera\xe7\xe3o de contas banidas por abuso grave ou CSAE: o necess\xe1rio para cumprir a lei. Dados agregados e an\xf3nimos de estat\xedsticas."]},{h:"Prazo",p:["Elimina\xe7\xe3o completa em at\xe9 30 dias ap\xf3s o pedido. Tamb\xe9m podes pedir para apagar apenas alguns dados (ex.: clipes ou hist\xf3rico) sem eliminar a conta."]}]}],r=n.map(e=>({href:"/".concat(e.slug),label:e.title,emoji:e.emoji}));function t(e){return n.find(a=>a.slug===e)}function d(e){let a=[],o=null;for(let s of e.split(/\n\s*\n/)){let e=s.trim().split("\n");if(e[0]){if(e[0].startsWith("## ")){o={h:e[0].slice(3).trim(),p:[]},a.push(o);let s=e.slice(1).join(" ").trim();s&&o.p.push(s)}else o||(o={h:"",p:[]},a.push(o)),o.p.push(e.join(" ").trim())}}return a}function c(e){return e.sections.map(e=>"## ".concat(e.h,"\n\n").concat(e.p.join("\n\n"))).join("\n\n")}}}]);